```rust
use std::sync::{Arc, Condvar, Mutex};
use std::thread;
use std::time::Duration;

// Counting permit pool `s` with exactly two permits.
// Implemented with a Mutex + Condvar so that a waiting worker blocks on the
// condition variable (not on the mutex), which means a permit holder can
// always acquire the mutex and release its permit (R5).
struct Semaphore {
    permits: Mutex<usize>,
    cv: Condvar,
}

impl Semaphore {
    fn new(n: usize) -> Semaphore {
        Semaphore {
            permits: Mutex::new(n),
            cv: Condvar::new(),
        }
    }

    fn acquire(&self) {
        let mut permits = self.permits.lock().unwrap();
        while *permits == 0 {
            // Wait releases the mutex while blocked, so holders can release.
            permits = self.cv.wait(permits).unwrap();
        }
        *permits -= 1;
    }

    fn release(&self) {
        let mut permits = self.permits.lock().unwrap();
        *permits += 1;
        self.cv.notify_one();
    }
}

fn worker(name: &'static str, s: Arc<Semaphore>) {
    // R3: acquire one permit, do the work, release the permit.
    s.acquire();
    // Simulate the worker's work while holding the permit.
    thread::sleep(Duration::from_millis(50));
    s.release();
    let _ = name; // role name kept for clarity; no extra output allowed (R7)
}

fn main() {
    // R2: one shared permit pool starting with exactly two permits.
    let s = Arc::new(Semaphore::new(2));

    // R1: supervising task launches w1, w2, w3 and waits for all of them.
    let s1 = Arc::clone(&s);
    let h1 = thread::spawn(move || worker("w1", s1));
    let s2 = Arc::clone(&s);
    let h2 = thread::spawn(move || worker("w2", s2));
    let s3 = Arc::clone(&s);
    let h3 = thread::spawn(move || worker("w3", s3));

    h1.join().unwrap();
    h2.join().unwrap();
    h3.join().unwrap();

    // R7: print exactly this line, then exit.
    println!("DONE done=1");
}
```

Notes on how the requirements are met:

- **R1**: `main` acts as the supervisor, spawning the three worker threads and joining each of them.
- **R2**: A single `Arc<Semaphore>` (`s`) is shared by all workers and is initialized with exactly `2` permits.
- **R3**: Each worker calls `s.acquire()`, does its work, then calls `s.release()`.
- **R4**: The semaphore only ever hands out a permit when `permits > 0`, so at most two workers hold permits concurrently; the third blocks in `cv.wait` until a release occurs.
- **R5**: `Condvar::wait` atomically releases the underlying mutex while the worker is blocked, so a permit holder is never blocked from entering `release()` and waking the waiter.
- **R6**: Every blocking wait is paired with a `notify_one` from `release`, and each worker always releases exactly the permit it acquired, so all schedules terminate.
- **R7**: The only output is the single line `DONE done=1`.
